import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"42、【益】 震下巽上","description":"橫渠易說 - 42、【益】 震下巽上","frontmatter":{"title":"42、【益】 震下巽上","description":"橫渠易說 - 42、【益】 震下巽上"},"headers":[],"relativePath":"classics/hengqu/044.md","filePath":"classics/hengqu/044.md"}'),l={name:"classics/hengqu/044.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_42、【益】-震下巽上" tabindex="-1">42、【益】 震下巽上 <a class="header-anchor" href="#_42、【益】-震下巽上" aria-label="Permalink to “42、【益】 震下巽上”">​</a></h1><h3 id="彖曰-益-損上益下-民說無疆。自上下下-其道大光。-利有攸往-中正有慶。-利涉大川-木道乃行。益動而巽-日進無疆。天施地生-其益無方。凡益之道-與時偕行。" tabindex="-1">彖曰：益，損上益下，民說無疆。自上下下，其道大光。“利有攸往”，中正有慶。“利涉大川”，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。 <a class="header-anchor" href="#彖曰-益-損上益下-民說無疆。自上下下-其道大光。-利有攸往-中正有慶。-利涉大川-木道乃行。益動而巽-日進無疆。天施地生-其益無方。凡益之道-與時偕行。" aria-label="Permalink to “彖曰：益，損上益下，民說無疆。自上下下，其道大光。“利有攸往”，中正有慶。“利涉大川”，木道乃行。益動而巽，日進無疆。天施地生，其益無方。凡益之道，與時偕行。”">​</a></h3><h3 id="象曰-風雷益-君子以見善則遷-有過則改。" tabindex="-1">象曰：風雷益，君子以見善則遷，有過則改。 <a class="header-anchor" href="#象曰-風雷益-君子以見善則遷-有過則改。" aria-label="Permalink to “象曰：風雷益，君子以見善則遷，有過則改。”">​</a></h3><p>上巽下動者，損上益下之道，木以動而巽，故“利涉大川”。否卦九四下而為初九，故曰“天施地生”，又曰“損上益下”，又曰“自上下下”。</p><h3 id="初九-利用為大作-元吉-無咎。-象曰-元吉無咎-下不厚事也。" tabindex="-1">初九，利用為大作，元吉，無咎。 象曰：“元吉無咎”，下不厚事也。 <a class="header-anchor" href="#初九-利用為大作-元吉-無咎。-象曰-元吉無咎-下不厚事也。" aria-label="Permalink to “初九，利用為大作，元吉，無咎。 象曰：“元吉無咎”，下不厚事也。”">​</a></h3><p>以剛陽之德施益於下，故利用大作。然必元吉乃無咎也。</p><h3 id="六二-或益之十朋之龜-弗克違-永貞吉。王用享於帝-吉。-象曰-或益之-自外來也。" tabindex="-1">六二，或益之十朋之龜，弗克違，永貞吉。王用享於帝，吉。 象曰：“或益之”，自外來也。 <a class="header-anchor" href="#六二-或益之十朋之龜-弗克違-永貞吉。王用享於帝-吉。-象曰-或益之-自外來也。" aria-label="Permalink to “六二，或益之十朋之龜，弗克違，永貞吉。王用享於帝，吉。 象曰：“或益之”，自外來也。”">​</a></h3><p>“或益之十朋之龜弗克違”，言損上益下之道，理不可易，人皆信之，雖十朋之龜亦不能違此道也。往見損，九五居中體柔，蒙上之益，修報於下，享帝之美，莫盛此焉。“或益之”，必有自外來而益之者也。</p><h3 id="六三-益之用凶事-無咎。有孚中行-告公用圭。-象曰-益用凶事-固有之也。" tabindex="-1">六三，益之用凶事，無咎。有孚中行，告公用圭。 象曰：益用凶事，固有之也。 <a class="header-anchor" href="#六三-益之用凶事-無咎。有孚中行-告公用圭。-象曰-益用凶事-固有之也。" aria-label="Permalink to “六三，益之用凶事，無咎。有孚中行，告公用圭。 象曰：益用凶事，固有之也。”">​</a></h3><p>中行者，不私於應，無所偏系也。用心不私，以拯兇難，雖非王者之佐，可以用之牧伯以為藩屏之臣矣。體躁居陽，上有剛應，持此施益，用拯兇難，乃其固能也，故無咎可必。然亦須執禮告上公而行，方閤中道，其曰“告公”者，未足專進為王者之佐也。</p><h3 id="六四-中行告公從-利用為依遷國。-象曰-告公從-以益志也。" tabindex="-1">六四，中行告公從，利用為依遷國。 象曰：“告公從”，以益志也。 <a class="header-anchor" href="#六四-中行告公從-利用為依遷國。-象曰-告公從-以益志也。" aria-label="Permalink to “六四，中行告公從，利用為依遷國。 象曰：“告公從”，以益志也。”">​</a></h3><p>以陰居陰，體巽應卑，持此施益，可以為依遷之國。純用卑柔，仍告上公見從，方可用事，無剛故也。不足告王，故曰“告公”。 本為初六，寄位於四，居陰體巽，所趨在下，以為依遷之國，人所容信，然必中行不私，然後可告必見從，蓋上以益下為心也。</p><h3 id="九五-有孚惠心勿問-元吉。有孚惠我德。-象曰-有孚惠心-勿問之矣。-惠我德-大得志也。" tabindex="-1">九五，有孚惠心勿問，元吉。有孚惠我德。 象曰：“有孚惠心”，勿問之矣。“惠我德”，大得志也。 <a class="header-anchor" href="#九五-有孚惠心勿問-元吉。有孚惠我德。-象曰-有孚惠心-勿問之矣。-惠我德-大得志也。" aria-label="Permalink to “九五，有孚惠心勿問，元吉。有孚惠我德。 象曰：“有孚惠心”，勿問之矣。“惠我德”，大得志也。”">​</a></h3><h3 id="上九-莫益之-或擊之-立心勿恆-兇。-象曰-莫益之-偏辭也。-或擊之-自外來也。" tabindex="-1">上九，莫益之，或擊之，立心勿恆，兇。 象曰：“莫益之”，偏辭也。“或擊之”，自外來也。 <a class="header-anchor" href="#上九-莫益之-或擊之-立心勿恆-兇。-象曰-莫益之-偏辭也。-或擊之-自外來也。" aria-label="Permalink to “上九，莫益之，或擊之，立心勿恆，兇。 象曰：“莫益之”，偏辭也。“或擊之”，自外來也。”">​</a></h3><p>體剛質巽，志應在下，位亢於上，故立心勿恆。“或擊之”，反“或益之”之義為文，故又云“自外來”也。 未嘗損己而云“莫益之”，作易者因益卦而言爾。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
